<?php if (!defined('ABSPATH')) { exit; } get_header(); ?>
<main id="main-content" class="container archive-main"><header class="archive-header"><span class="eyebrow">JELAJAHI PEMBAHASAN</span><h1><?php echo esc_html(is_category() || is_tag() ? single_term_title('', false) : get_the_archive_title()); ?></h1><?php if (get_the_archive_description()) : ?><div class="archive-description"><?php echo wp_kses_post(get_the_archive_description()); ?></div><?php endif; ?></header>
